INSERT INTO dump_descriptions (base_key, description) VALUES ('cdcompat-0.2.0-alpha.4-drg0923', 'Integrates the CD1 and CD2 custom-difficulty engines behind an in-game engine and difficulty selector; this experimental build targets the 2026-09-23 game update.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('candidates', 'Bundles 15 experimental generated custom-difficulty JSON presets, each defining its own enemy roster, wave spawners, pools, resupply rules, and caps.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
